///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — speclListTpCd

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_hiddenText", attr: "label", fn: function () { return String(dma_comInfo.get("exstDeadlineRemk")); } },
        { childId: "txa_hiddenText2", attr: "label", fn: function () { return String(dma_comInfo.get("remk")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "ipt_comNm", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) ==='06'); } }, { id: "ipt_comAbbrv", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) ==='06'); } }, { id: "if_listTpClssCd_2", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !=='06'); } }, { id: "tr_80", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !=='06'); } }, { id: "if_billSubmitDd", fn: function(){ return ((String(((dma_comInfo.get("billSubmitDd") ?? (() => { throw new Error("unresolved:" + "comInfo.billSubmitDd"); })())) == null ? '' : ((dma_comInfo.get("billSubmitDd") ?? (() => { throw new Error("unresolved:" + "comInfo.billSubmitDd"); })()))).length === 0)); } }, { id: "if_billSubmitDd_2", fn: function(){ return (!(String(((dma_comInfo.get("billSubmitDd") ?? (() => { throw new Error("unresolved:" + "comInfo.billSubmitDd"); })())) == null ? '' : ((dma_comInfo.get("billSubmitDd") ?? (() => { throw new Error("unresolved:" + "comInfo.billSubmitDd"); })()))).length === 0)); } }, { id: "if_listTpClssCd_3", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !=='06' &&  (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !=='02'); } }, { id: "tr_111", fn: function(){ return ((dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !=='06' &&  (dma_comInfo.get("listTpClssCd") ?? (() => { throw new Error("unresolved:" + "comInfo.listTpClssCd"); })()) !=='02'); } }, { id: "ipt_comAbbrv_2", fn: function(){ return ((String(((dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })())) == null ? '' : ((dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })()))).length === 0) || (dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })()) === ''); } }, { id: "ipt_comAbbrv2", fn: function(){ return (!(String(((dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })())) == null ? '' : ((dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })()))).length === 0) && (dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })()) !== ''); } }, { id: "ipt_comEngNm", fn: function(){ return ((String(((dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })())) == null ? '' : ((dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })()))).length === 0) || (dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })()) === ''); } }, { id: "ipt_comEngNm_2", fn: function(){ return (!(String(((dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })())) == null ? '' : ((dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })()))).length === 0) && (dma_comInfo.get("comAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comAbbrv"); })()) !== ''); } }, { id: "ipt_comEngAbbrv", fn: function(){ return ((String(((dma_comInfo.get("comEngAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comEngAbbrv"); })())) == null ? '' : ((dma_comInfo.get("comEngAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comEngAbbrv"); })()))).length === 0) || (dma_comInfo.get("comEngAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comEngAbbrv"); })()) === ''); } }, { id: "ipt_comEngAbbrv_2", fn: function(){ return (!(String(((dma_comInfo.get("comEngAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comEngAbbrv"); })())) == null ? '' : ((dma_comInfo.get("comEngAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comEngAbbrv"); })()))).length === 0) && (dma_comInfo.get("comEngAbbrv") ?? (() => { throw new Error("unresolved:" + "comInfo.comEngAbbrv"); })()) !== ''); } }, { id: "btn_Register", fn: function(){ return ((dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 32 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 33 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 34 && (dma_comInfo.get("listProcsStat") ?? (() => { throw new Error("unresolved:" + "comInfo.listProcsStat"); })()) !== 36); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_speclListTpCd", fn: function () { return String(String((dma_pageContext.get("speclListTpCd") ?? ""))); } },
        { childId: "ipt_comAbbrv", fn: function () { return String(String(dma_comInfo.get("comNm")).substring(0, 20)); } },
        { childId: "__rb0", fn: function () { return String(dma_comInfo.get("comNm")) + "(" + String(dma_comInfo.get("isurCd")) + ")"; } },
        { childId: "__rb1", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "ipt_corpRegNo1", fn: function () { return String(String(dma_comInfo.get("corpRegNo")).substring(0, 6)); } },
        { childId: "ipt_corpRegNo2", fn: function () { return String(String(dma_comInfo.get("corpRegNo")).substring(6, 13)); } },
        { childId: "ipt_bzRegNo1", fn: function () { return String(String(dma_comInfo.get("bzRegNo")).substring(0, 3)); } },
        { childId: "ipt_bzRegNo2", fn: function () { return String(String(dma_comInfo.get("bzRegNo")).substring(3, 5)); } },
        { childId: "ipt_bzRegNo3", fn: function () { return String(String(dma_comInfo.get("bzRegNo")).substring(5, 10)); } },
        { childId: "cal_billSubmitDd", fn: function () { return String((dma_pageContext.get("year") ?? "")) + String((dma_pageContext.get("monthStr") ?? "")) + String((dma_pageContext.get("dayStr") ?? "")); } },
        { childId: "ipt_acntclsMmdd1", fn: function () { return String(String((dma_pageContext.get("acntclsMmdd") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        form = (document.preListForm || { elements: [] });
        scwin.setLeadcomVars();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil51010n2.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51010n2' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — jldfil51010n2: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.l =screen.width/2 - scwin.w/2; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51010n2' }); }

try { scwin.t =screen.height/2 - scwin.h/2; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil51010n2' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil51010n2.onpageload' });
    }
};

