/**
 * @method
 * @name checkCorpRegNo
 * @description check Corp Reg No 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCorpRegNo = async function () {
    let corpRegNo1 = $c.util.getComponent('ipt_corpRegNo1').getValue(); if (corpRegNo1 == null) { corpRegNo1 = ''; }
    let corpRegNo2 = $c.util.getComponent('ipt_corpRegNo2').getValue(); if (corpRegNo2 == null) { corpRegNo2 = ''; }
    const corpRegNo = corpRegNo1 + corpRegNo2;
    if (corpRegNo1 === '') {
        await $c.win.alert('법인등록번호가 입력되지 않았습니다');
        $c.util.getComponent('ipt_corpRegNo1').select();
        return false;
    }
    if (corpRegNo2 === '') {
        await $c.win.alert('법인등록번호가 입력되지 않았습니다');
        $c.util.getComponent('ipt_corpRegNo2').select();
        return false;
    }
    if (isNaN(corpRegNo)) {
        await $c.win.alert('법인등록번호는 숫자만 입력하세요');
        return false;
    }
    if (corpRegNo.length !== 13) {
        await $c.win.alert('법인등록번호가 잘못되었습니다');
        return false;
    }
    return true;
};

