/**
 * @method
 * @name chkEmail
 * @description chk Email 처리
 * @param {*} el el
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkEmail = async function (el) {
    const val = el.value;
    if (val !== "") {
        const pattern = /^[_a-zA-Z0-9-\.]+@[\.a-zA-Z0-9-]+\.[a-zA-Z]+$/;
        if (!pattern.test(val)) {
            await $c.win.alert("E-mail 형식에 맞지않습니다.");
            el.focus();
        }
    }
};

/**
 * @method
 * @name chkPhone
 * @description chk Phone 처리
 * @param {*} el el
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkPhone = async function (el) {
    const val = el.value;
    if (val !== "") {
        const pattern = /^(0[2-8][0-5]?|01[01346-9])-?([1-9]{1}[0-9]{2,3})-?([0-9]{4})$/;
        if (!pattern.test(val)) {
            await $c.win.alert("전화번호 형식에 맞지않습니다.");
            el.focus();
        }
    }
};

