scwin.getStringSize = function (message) {
    let i, len = 0;
    for (i = 0; i < message.length; i++) {
        (message.charCodeAt(i) > 255) ? len += 2 : len++;
    }
    return len;
};

/**
 * @method
 * @name popZipCode
 * @description pop Zip Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popZipCode = async function () {
    const zipSearchURL = '/jldinf90009/jldinf90009.xml';
    scwin.setZipCode_recv(await $c.win.openPopup(zipSearchURL, { id: "zipWin", scrollbars: false, resizable: false, width: "445", height: "600", type: "pageFramePopup" }, Object.assign({ method: "loadInitPage" }, { zipCodeWin: (typeof scwin.zipCodeWin !== 'undefined' ? scwin.zipCodeWin : undefined) })));
};

/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} _zipCode _zipCode
 * @param {*} _address _address
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function (_zipCode, _address) {
    $c.util.getComponent("ipt_zipcd").setValue(_zipCode);
    $c.util.getComponent("ipt_comAddr").setValue(_address);
};

/**
 * @method
 * @name checkValueSet
 * @description check Value Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkValueSet = function () {
    const frm = (document.preListForm || { elements: [] });
    if ($c.util.getComponent('slc_prelmInvstgComTpCd').getValue()=== "1") {
        $("input:radio[name='ventAhthYn']:radio[value='Y']").attr("checked", true);
        $("input:radio[name='innoBizAhthYn']:radio[value='N']").attr("checked", true);
    } else {
        if ($c.util.getComponent('slc_prelmInvstgComTpCd').getValue()=== "6") {
            $("input:radio[name='ventAhthYn']:radio[value='N']").attr("checked", true);
            $("input:radio[name='innoBizAhthYn']:radio[value='Y']").attr("checked", true);
        } else {
            if ($c.util.getComponent('slc_prelmInvstgComTpCd').getValue()=== "7") {
                $("input:radio[name='ventAhthYn']:radio[value='Y']").attr("checked", true);
                $("input:radio[name='innoBizAhthYn']:radio[value='Y']").attr("checked", true);
            } else {
                if ($c.util.getComponent('slc_prelmInvstgComTpCd').getValue()=== "2") {
                    $("input:radio[name='ventAhthYn']:radio[value='N']").attr("checked", true);
                    $("input:radio[name='innoBizAhthYn']:radio[value='N']").attr("checked", true);
                }
            }
        }
    }
};

/**
 * @method
 * @name setCorpInfo_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };

